function addCustomCommunityData(c){communities.push({...c,groups:[['Announcements',c.announcement,'1']]});opportunities.push({...sampleOpportunity('opp-'+c.id,c.announcement,c.name,c.topic,[c.id],'A sample announcement about '+c.topic+' in your own demo community. Add it to your interests to see it here.'),tags:[c.topic,...(/sport|football|badminton|running|cricket|fitness/i.test(c.topic)?['Sports']:[])]});}
state.customCommunities=state.customCommunities.filter(c=>c&&typeof c.id==='string'&&typeof c.name==='string'&&typeof c.topic==='string'&&typeof c.announcement==='string');
